const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='content-studio-v1';
const templates={
'Outfit transition':{title:'One outfit, three different moods',hook:'“Same outfit. Which version wins?”',shots:'Film three fully clothed styling variations from the same camera position. Start with the finished looks, then show one quick transition for each. End on a choice between A, B, and C.',setup:'Indoor · tripod · three accessories',batch:'Indoor / tripod',duration:'12–18 seconds',caption:'Ask viewers to pick their favorite styling direction.'},
'POV / personality':{title:'The off-camera version of me',hook:'“What you think my morning looks like vs. reality.”',shots:'Record a polished opening, then cut to an everyday moment such as coffee, outfit indecision, or a missed alarm. Finish with a candid reaction.',setup:'Indoor · phone · everyday props',batch:'Indoor / tripod',duration:'10–15 seconds',caption:'Invite followers to share their own morning reality.'},
'Behind the scenes':{title:'From setup to final shot',hook:'“This tiny corner became the whole shoot.”',shots:'Show the location before styling, a quick lighting adjustment, and a fully clothed final pose. Keep private information and unreleased material out of the frame.',setup:'Indoor · existing shoot setup',batch:'Indoor / tripod',duration:'15–20 seconds',caption:'Ask whether viewers want another look at the creative process.'},
'Q&A':{title:'Three things you asked me',hook:'“You keep asking, so here are my answers.”',shots:'Choose three non-sensitive questions about hobbies, style, or creative work. Film a short answer to each with clear on-screen question text.',setup:'Indoor · quiet space · phone',batch:'Indoor / talking',duration:'20–30 seconds',caption:'Invite one question for the next installment.'},
'Lifestyle':{title:'Come with me: the little reset',hook:'“A 20-minute reset before a busy day.”',shots:'Capture three simple moments: making a drink, stepping outside, and preparing for the day. Record a short voiceover afterward; avoid revealing a live location.',setup:'Daylight · phone · casual outfit',batch:'Daylight / handheld',duration:'15–25 seconds',caption:'Ask followers about their favorite small routine.'}
};
function fresh(){return {version:1,demo:true,model:{name:'Sample model',platform:'Instagram Reels',baseline:5000,start:new Date().toLocaleDateString('en-CA'),slots:8,boundaries:'Fully clothed public content. No identifying locations.',voice:'Playful, confident, conversational'},research:[{id:'s1',title:'Three-look styling transition',format:'Outfit transition',kind:'Own post',views:14200,url:'',date:'2026-10-10',notes:'Fictional example: followers responded to the A/B/C choice.'},{id:'s2',title:'A candid morning moment',format:'POV / personality',kind:'Own post',views:8700,url:'',date:'2026-10-09',notes:'Fictional example: relatable opening and short runtime.'},{id:'s3',title:'A look at the photo setup',format:'Behind the scenes',kind:'Reference',views:21000,url:'',date:'2026-10-08',notes:'Fictional example: fast before/after reveal.'}],ideas:[]};}
const agencyKey='content-studio-v2';
let agency, state, storageProblem=false;
try {
 const saved=localStorage.getItem(agencyKey);
 if(saved){ agency=JSON.parse(saved); if(agency.version!==2||!Array.isArray(agency.models)||!agency.models.length) throw Error('Invalid workspace'); agency.models.forEach(validateModel); if(agency.models.some(m=>!m.id)||new Set(agency.models.map(m=>m.id)).size!==agency.models.length)throw Error('Invalid model IDs'); }
 else {const legacy=localStorage.getItem(key); const first=legacy?JSON.parse(legacy):fresh();first.id=crypto.randomUUID();agency={version:2,activeId:first.id,models:[first]};}
} catch {storageProblem=true; const first=fresh();first.id=crypto.randomUUID();agency={version:2,activeId:first.id,models:[first]};}
state=agency.models.find(m=>m.id===agency.activeId)||agency.models[0];agency.activeId=state.id;
let view='models';
function save(){if(storageProblem){notice('Could not read saved data. This session will not overwrite it. Export a backup before closing.');return}try{localStorage.setItem(agencyKey,JSON.stringify(agency))}catch{notice('Browser storage is full or unavailable. Export a backup before closing.')}}
function notice(t){$('#notice').textContent=t}
function ratio(r){return r.kind==='Own post'&&state.model.baseline>0&&r.views>0?r.views/state.model.baseline:null}
function evidence(r){const n=r&&ratio(r);return !r?'Experiment · no source':n?`${n.toFixed(1)}× typical views · ${state.demo?'sample':'entered'} data`:'Reference inspiration · unvalidated'}
function ranked(){return [...state.research].sort((a,b)=>(ratio(b)||0)-(ratio(a)||0))}
function generate(){const existing=new Set(state.ideas.map(i=>i.source||'experiment-'+i.format));let count=0;for(const r of ranked()){if(existing.has(r.id))continue;state.ideas.push({id:crypto.randomUUID(),format:r.format,source:r.id,approved:false});count++}for(const f of Object.keys(templates)){if(state.ideas.some(i=>i.format===f))continue;state.ideas.push({id:crypto.randomUUID(),format:f,source:null,approved:false});count++}save();render();notice(count?`${count} briefs prepared from format templates. Review and edit before approving.`:'All current research already has a brief. Add a new observation to create more.');}
function approved(){return state.ideas.filter(i=>i.approved).slice(0,Number(state.model.slots))}
function brief(i){return {...templates[i.format],...i.edits}}
function scheduled(){const rows=approved();return rows.map((i,n)=>{const d=new Date(state.model.start+'T12:00:00');d.setDate(d.getDate()+Math.floor(n*14/Math.max(rows.length,1)));return {i,date:d.toLocaleDateString('en-CA'),day:Math.floor(n*14/Math.max(rows.length,1))}})}
function safeLink(url){try{const u=new URL(url);return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return ''}}
function render(){renderSwitcher();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#mode').textContent=state.demo?'SAMPLE WORKSPACE':'YOUR WORKSPACE';$('#heading').textContent={models:'Your talent. One workspace.',ideas:'Make the next shoot count.',research:'Find the signal.',plan:'Two weeks. One clear brief.',setup:'Make it her own.'}[view];$('#subtitle').textContent={models:'Choose a model to open her profile, ideas, and filming plan.',ideas:`${state.model.name} · Research-backed directions, ready for your review.`,research:'Capture observations. Separate evidence from inspiration.',plan:'Turn approved ideas into a filming plan she can actually use.',setup:'A few clear constraints make every brief more useful.'}[view];({models:renderModels,ideas:renderIdeas,research:renderResearch,plan:renderPlan,setup:renderSetup}[view])()}
function renderIdeas(){$('#content').innerHTML=`<div class="stats"><div class="stat"><span class="eyebrow">RESEARCH SIGNALS</span><strong>${state.research.length.toString().padStart(2,'0')}</strong><small>Observations in your inbox</small></div><div class="stat"><span class="eyebrow">CREATIVE DIRECTIONS</span><strong>${state.ideas.length.toString().padStart(2,'0')}</strong><small>Template-assisted briefs</small></div><div class="stat"><span class="eyebrow">READY TO FILM</span><strong>${approved().length.toString().padStart(2,'0')}</strong><small>Approved for this cycle</small></div></div><div class="hero"><div><span class="eyebrow" style="color:#dceda7">FROM RESEARCH TO ACTION</span><h2>Turn a strong signal into her next idea.</h2><p>Draft from your observations, fill gaps with clearly labeled experiments, then approve the best fit.</p></div><button id="generate">✦ Draft ideas</button></div><div class="bar"><h2>The idea desk</h2><span class="meta">Own-post view lift first · references and experiments follow</span></div><div class="grid">${[...state.ideas].sort((a,b)=>(ratio(state.research.find(r=>r.id===b.source)||{})||0)-(ratio(state.research.find(r=>r.id===a.source)||{})||0)).map(i=>{const t=brief(i),r=state.research.find(r=>r.id===i.source);return `<article class="card ${i.approved?'approved':''}"><div class="card-top"><span class="tag">${esc(i.format)}</span><span class="meta">${esc(t.duration)}</span></div><h3>${esc(t.title)}</h3><p class="hook">${esc(t.hook)}</p><p>${esc(evidence(r))}</p><details><summary>Open filming brief</summary><p><b>Capture:</b> ${esc(t.shots)}</p><p><b>Setup:</b> ${esc(t.setup)}</p><p><b>Caption direction:</b> ${esc(t.caption)}</p><p><b>Brand voice:</b> ${esc(state.model.voice)}</p><p><b>Boundaries:</b> ${esc(state.model.boundaries)}</p><p><b>Evidence:</b> ${r?esc(r.title+' · '+r.date+' · '+r.notes):'No observed source. Test this format before repeating.'}</p>${r&&safeLink(r.url)?`<a href="${esc(safeLink(r.url))}" target="_blank" rel="noopener noreferrer">Open reference ↗</a>`:''}<button class="subtle" data-edit="${i.id}">Edit title, hook & shots</button></details><div class="card-bottom"><span class="meta">${esc(t.batch)}</span><button data-approve="${i.id}" class="${i.approved?'secondary':''}">${i.approved?'✓ Approved · undo':'Approve idea'}</button></div></article>`}).join('')}</div>${!state.ideas.length?'<div class="empty">Your idea desk is ready. Add research or draft from the sample workspace.</div>':''}`;$('#generate').onclick=generate;document.querySelectorAll('[data-approve]').forEach(b=>b.onclick=()=>{let i=state.ideas.find(i=>i.id===b.dataset.approve);if(!i.approved&&state.ideas.filter(x=>x.approved).length>=Number(state.model.slots)){notice('The cycle is full. Unapprove an idea or increase the post target in settings.');return}i.approved=!i.approved;save();render()});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const i=state.ideas.find(i=>i.id===b.dataset.edit),t=brief(i);$('#content').innerHTML=`<div class="panel"><h2>Edit filming brief</h2><form id="edit"><label>Title<input name="title" value="${esc(t.title)}" required></label><label>Opening hook<input name="hook" value="${esc(t.hook)}" required></label><label>Shots<textarea name="shots" required>${esc(t.shots)}</textarea></label><div class="bar"><button>Save brief</button><button type="button" id="cancel" class="secondary">Cancel</button></div></form></div>`;$('#cancel').onclick=render;$('#edit').onsubmit=e=>{e.preventDefault();i.edits=Object.fromEntries(new FormData(e.target));save();render()}})}
function renderResearch(){$('#content').innerHTML=`<div class="panel"><h2>Add an observation</h2><p class="help">Paste a source and what worked. Nothing is fetched automatically. Views rank your own posts against the baseline you enter; reference views are not comparable.</p><form id="research-form" class="form-grid"><label>Video / observation title<input name="title" required maxlength="150" placeholder="e.g. Three-look transition with a choice at the end"></label><label>Source URL<input name="url" type="url" placeholder="https://..."></label><label>Format<select name="format">${Object.keys(templates).map(f=>`<option>${f}</option>`).join('')}</select></label><label>Source type<select name="kind"><option>Own post</option><option>Reference</option></select></label><label>Views<input name="views" type="number" min="0" step="1" placeholder="Leave blank if unknown"></label><label>Date observed<input name="date" type="date" required value="${new Date().toLocaleDateString('en-CA')}"></label><label class="wide">What worked?<textarea name="notes" required placeholder="Describe the hook, payoff, audience response, or useful pattern."></textarea></label><div><button>Add to research</button></div></form></div><div class="bar"><h2>Research inbox</h2><span class="meta">${state.demo?'Fictional sample observations':'Your entered observations'}</span></div><div class="panel">${ranked().map(r=>`<div class="record"><div><h3>${esc(r.title)}</h3><span class="tag">${esc(r.format)}</span><p>${esc(r.notes)}</p><div class="meta">${esc(r.date)} · ${r.views?r.views.toLocaleString()+' views':'Views unknown'} · ${esc(evidence(r))}</div>${safeLink(r.url)?`<a href="${esc(safeLink(r.url))}" target="_blank" rel="noopener noreferrer">Source ↗</a>`:''}</div><button class="subtle" data-delete="${r.id}">Remove</button></div>`).join('')||'<p>No observations yet.</p>'}</div>`;$('#research-form').onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));o.id=crypto.randomUUID();o.views=o.views===''?null:Number(o.views);state.research.push(o);save();render();notice('Observation saved. Use Draft ideas on the idea desk to make its brief.')};document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{state.research=state.research.filter(r=>r.id!==b.dataset.delete);state.ideas.forEach(i=>{if(i.source===b.dataset.delete)i.source=null});save();render()})}
function renderPlan(){const rows=scheduled(),groups={};rows.forEach(({i})=>(groups[brief(i).batch]??=[]).push(brief(i).title));$('#content').innerHTML=`<div class="hero"><div><span class="eyebrow" style="color:#dceda7">${esc(state.model.name)} · ${esc(state.model.platform)}</span><h2>${rows.length} posts. ${Object.keys(groups).length} filming setup${Object.keys(groups).length===1?'':'s'}.</h2><p>Batch by setup, then publish across the fortnight. Empty days stay open for replies, review, and rest.</p></div><button id="export-plan" ${rows.length?'':'disabled'}>↓ Export filming brief</button></div><div class="bar"><h2>Film together</h2><span class="meta">Suggested grouping · agency to arrange shoot dates</span></div>${Object.entries(groups).map(([g,ts])=>`<div class="batch"><b>${esc(g)}</b><p>${ts.map(esc).join(' · ')}</p></div>`).join('')||'<div class="empty">Approve ideas on the idea desk to build your plan.</div>'}<div class="bar"><h2>Your next 14 days</h2><span class="meta">Starts ${esc(state.model.start)}</span></div><div class="calendar">${Array.from({length:14},(_,n)=>{const d=new Date(state.model.start+'T12:00:00');d.setDate(d.getDate()+n);const row=rows.find(r=>r.day===n);return `<article class="day ${row?'':'rest'}"><time>${esc(d.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'}))}</time><h3>${row?esc(brief(row.i).title):'Community / open day'}</h3><p>${row?esc(brief(row.i).hook):'Reply, review audience questions, or leave space.'}</p>${row?`<span class="tag">${esc(state.model.platform)}</span>`:''}</article>`}).join('')}</div>`;$('#export-plan').onclick=()=>{download('two-week-filming-brief.txt',`${state.demo?'SAMPLE DATA — DEMONSTRATION ONLY\n\n':''}${state.model.name} — TWO-WEEK FILMING BRIEF\nStart: ${state.model.start}\nPlatform: ${state.model.platform}\nVoice: ${state.model.voice}\nBoundaries: ${state.model.boundaries}\n\nFILM TOGETHER\n${Object.entries(groups).map(([g,ts])=>g+'\n'+ts.map(t=>' • '+t).join('\n')).join('\n\n')}\n\nPOSTING PLAN\n${rows.map(({i,date})=>{const t=brief(i),r=state.research.find(r=>r.id===i.source);return `${date} — ${t.title}\nHook: ${t.hook}\nCapture: ${t.shots}\nSetup: ${t.setup}\nLength: ${t.duration}\nCaption: ${t.caption}\nEvidence: ${evidence(r)}${r?'\nSource: '+r.title+' · '+r.date+' '+r.url:''}`}).join('\n\n')}\n\nReview all briefs before filming. No live trend research or automatic posting.\n`,'text/plain')}}
function renderBaseSetup(){$('#content').innerHTML=`<div class="panel"><h2>The model profile</h2><form id="settings" class="form-grid"><label>Model / working name<input name="name" value="${esc(state.model.name)}" required></label><label>Primary platform<select name="platform">${['Instagram Reels','TikTok','YouTube Shorts','X — SFW'].map(p=>`<option ${state.model.platform===p?'selected':''}>${p}</option>`).join('')}</select></label><label>Typical views per comparable post<input name="baseline" type="number" min="0" value="${state.model.baseline}" required><span class="help">Use a recent median for similar formats and post age. 0 = unknown.</span></label><label>Cycle start<input name="start" type="date" value="${esc(state.model.start)}" required></label><label>Post target / fortnight<input name="slots" type="number" min="1" max="14" step="1" value="${state.model.slots}" required></label><label>Brand voice<input name="voice" value="${esc(state.model.voice)}" required></label><label class="wide">Boundaries and filming constraints<textarea name="boundaries" required>${esc(state.model.boundaries)}</textarea></label><div><button>Save profile</button></div></form></div><div class="bar"><h2>Start your pilot</h2></div><div class="panel"><p>This prototype uses browser-local storage and a fixed library of SFW formats. It drafts briefs, prioritizes entered observations, groups shoots, and exports plans. Live research, AI generation, shared agency access, and scheduled collection are not connected.</p><button class="secondary" id="clear">Clear this model’s sample research & ideas</button><p class="help">Clears observations and ideas for the selected model only. Export a backup first if needed.</p></div>`;$('#settings').onsubmit=e=>{e.preventDefault();const m={...state.model,...Object.fromEntries(new FormData(e.target))};m.slots=Number(m.slots);m.baseline=Number(m.baseline);if(state.ideas.filter(i=>i.approved).length>m.slots){notice('Unapprove some ideas before lowering the post target below the approved count.');return}state.model=m;save();render();notice('Profile saved.')};$('#clear').onclick=()=>{if(!confirm('Clear observations and ideas for this model? Other models and this profile will be kept.'))return;state.demo=false;state.research=[];state.ideas=[];if(state.model.name==='Sample model')state.model.name='My model';save();render();notice('Your workspace is ready. Add research to begin.')}}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{if(!leaveForm())return;view=b.dataset.view;notice('');render()});
$('#backup').onclick=()=>download('content-studio-all-models.json',JSON.stringify(agency,null,2),'application/json');
$('#restore').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;const o=JSON.parse(await file.text());let incoming;if(o.version===1){validateModel(o);o.id=crypto.randomUUID();incoming={version:2,activeId:o.id,models:[o]};}else{if(o.version!==2||!Array.isArray(o.models)||!o.models.length)throw Error();o.models.forEach(validateModel);if(o.models.some(m=>!m.id))throw Error();if(new Set(o.models.map(m=>m.id)).size!==o.models.length||!o.models.some(m=>m.id===o.activeId))throw Error();incoming=o;}if(!confirm('Replace ALL model profiles in this browser with this backup? Export your current workspace first if needed.'))return;agency=incoming;state=agency.models.find(m=>m.id===agency.activeId);storageProblem=false;save();view='models';render();notice('Model workspace restored.')}catch{notice('Could not restore this file. Choose a valid Content Studio backup.')}e.target.value=''};
let dirty=false;
function leaveForm(){return !dirty||confirm('Leave without saving these profile changes?')}
function avatar(m,large=false){const photo=m.photo&&/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(m.photo)?m.photo:null;return `<div class="avatar ${large?'large':''}">${photo?`<img src="${photo}" alt="${esc(m.name)} profile photo">`:esc(m.name.trim().split(/\s+/).map(s=>s[0]).slice(0,2).join('').toUpperCase()||'?')}</div>`}
function renderSwitcher(){dirty=false;$('#model-switcher').innerHTML=`<label for="active-model">CURRENT MODEL</label><select id="active-model" aria-label="Switch model">${agency.models.map(m=>`<option value="${esc(m.id)}" ${m.id===state.id?'selected':''}>${esc(m.model.name)}${m.demo?' · sample':''}</option>`).join('')}</select>`;$('#active-model').onchange=e=>{if(!leaveForm()){e.target.value=state.id;return}switchModel(e.target.value,view==='models'?'setup':view)}}
function switchModel(id,next='setup'){const m=agency.models.find(m=>m.id===id);if(!m)return;state=m;agency.activeId=id;view=next;save();notice('');render()}
function renderModels(){$('#mode').textContent=`${agency.models.length} MODEL${agency.models.length===1?'':'S'}`;$('#content').innerHTML=`<div class="hero"><div><span class="eyebrow" style="color:#dceda7">YOUR MODEL ROSTER</span><h2>Start with the person behind the content.</h2><p>Each profile holds her voice, preferences, and a separate planning workspace. Switch models anytime using the sidebar.</p></div><button id="add-model">+ Add model</button></div><div class="bar"><h2>Model profiles</h2><span class="meta">Saved in this browser · export all models for backup</span></div><div class="grid">${agency.models.map(m=>`<article class="card profile-card">${avatar(m.model,true)}<div class="card-top"><h3>${esc(m.model.name)}</h3><span class="tag">${m.demo?'Sample':m.id===state.id?'Selected':'Profile'}</span></div><p>${esc(m.model.voice||'Add her personality and voice.')}</p><span class="meta">${esc(m.model.platform)} · ${m.model.slots} posts / fortnight</span><div class="profile-metrics"><span><b>${m.research.length}</b> observations</span><span><b>${m.ideas.filter(i=>i.approved).length}</b> approved ideas</span></div><div class="card-bottom"><button data-open-model="${esc(m.id)}">Open profile</button><button class="secondary" data-model-plan="${esc(m.id)}">View plan</button></div></article>`).join('')}</div>`;$('#add-model').onclick=renderNewModel;document.querySelectorAll('[data-open-model]').forEach(b=>b.onclick=()=>switchModel(b.dataset.openModel));document.querySelectorAll('[data-model-plan]').forEach(b=>b.onclick=()=>switchModel(b.dataset.modelPlan,'plan'))}
function renderNewModel(){$('#content').innerHTML=`<div class="panel"><span class="eyebrow">NEW MODEL</span><h2>Start with a name.</h2><p>Her workspace starts empty. You can fill in social profiles and filming preferences next.</p><form id="new-model"><label>Model / working name<input name="name" maxlength="100" required placeholder="Enter her working name" autofocus></label><div class="bar"><button>Create profile</button><button type="button" class="secondary" id="cancel-model">Cancel</button></div></form></div>`;$('#new-model').oninput=()=>dirty=true;$('#cancel-model').onclick=()=>{if(leaveForm())render()};$('#new-model').onsubmit=e=>{e.preventDefault();const name=new FormData(e.target).get('name').trim();if(!name){notice('Enter a model name.');return}const m=fresh();m.id=crypto.randomUUID();m.demo=false;m.research=[];m.ideas=[];m.model={...m.model,name,baseline:0,voice:'',boundaries:'',goal:'',handles:'',locations:'',wardrobe:'',availability:'',photo:''};agency.models.push(m);switchModel(m.id);notice('Profile created. Add the details that will guide her content.')};}
function renderSetup(){renderBaseSetup();const form=$('#settings');const fields=[['handles','Social profiles','Public profile URLs or @handles, one per line.'],['goal','Main objective','What should her content achieve?'],['locations','Available filming locations','e.g. home studio, garden, gym with permission'],['wardrobe','Outfits & styling','Her preferred looks and available wardrobe'],['availability','Filming availability','e.g. Tuesdays, one 90-minute session each week']];form.querySelector('[name="name"]').maxLength=100;const imagePanel=document.createElement('div');imagePanel.className='profile-banner';imagePanel.innerHTML=`${avatar(state.model,true)}<div><h2>${esc(state.model.name)}</h2><p>${state.demo?'Sample profile · explore or replace with your model’s details.':'Her research, ideas, and plan stay with this profile.'}</p><label class="upload">Choose profile photo<input id="profile-photo" type="file" accept="image/png,image/jpeg,image/webp"></label><span class="help">PNG, JPG, or WebP · up to 500 KB · saved with this profile</span><button type="button" class="subtle" id="remove-photo">Remove photo</button></div></div>`;form.before(imagePanel);for(const [name,label,placeholder] of fields){const node=document.createElement('label');node.className='wide';node.innerHTML=`${label}<textarea name="${name}" placeholder="${esc(placeholder)}">${esc(state.model[name]||'')}</textarea>`;form.insertBefore(node,form.lastElementChild)}let photo=state.model.photo||'';form.oninput=()=>dirty=true;$('#profile-photo').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>500000){notice('Choose a PNG, JPG, or WebP smaller than 500 KB.');return}const reader=new FileReader();reader.onload=()=>{photo=reader.result;dirty=true;imagePanel.querySelector('.avatar').innerHTML=`<img src="${photo}" alt="Profile photo preview">`;notice('Photo ready. Save profile to keep it.')};reader.readAsDataURL(f)};$('#remove-photo').onclick=()=>{photo='';dirty=true;imagePanel.querySelector('.avatar').textContent=state.model.name.slice(0,2).toUpperCase();notice('Photo removed from the draft. Save profile to keep the change.')};form.onsubmit=e=>{e.preventDefault();const m={...state.model,...Object.fromEntries(new FormData(form)),photo};m.name=m.name.trim();if(!m.name){notice('Enter a model name.');return}m.slots=Number(m.slots);m.baseline=Number(m.baseline);if(state.ideas.filter(i=>i.approved).length>m.slots){notice('Unapprove some ideas before lowering the post target below the approved count.');return}state.model=m;save();render();notice('Profile saved for '+m.name+'.')};}
function validateModel(o){if(!o||typeof o.demo!=='boolean'||!o.model||!Array.isArray(o.research)||!Array.isArray(o.ideas))throw Error();if(o.version!==1)throw Error();if(o.id!==undefined&&(typeof o.id!=='string'||!/^[a-zA-Z0-9-]+$/.test(o.id)))throw Error();const m=o.model;if(!['name','platform','start','voice','boundaries'].every(k=>typeof m[k]==='string')||!m.name.trim()||!/^\d{4}-\d{2}-\d{2}$/.test(m.start)||!Number.isFinite(new Date(m.start).getTime())||!Number.isInteger(m.slots)||m.slots<1||m.slots>14||!Number.isFinite(m.baseline)||m.baseline<0)throw Error();for(const k of ['photo','goal','handles','locations','wardrobe','availability'])if(m[k]!==undefined&&typeof m[k]!=='string')throw Error();if(m.photo&&(!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(m.photo)||m.photo.length>700000))throw Error();if(!o.research.every(r=>r&&typeof r.id==='string'&&/^[a-zA-Z0-9-]+$/.test(r.id)&&Object.hasOwn(templates,r.format)&&['title','notes','date','url'].every(k=>typeof r[k]==='string')&&['Own post','Reference'].includes(r.kind)&&(r.views===null||(Number.isFinite(r.views)&&r.views>=0)))||!o.ideas.every(i=>i&&typeof i.id==='string'&&/^[a-zA-Z0-9-]+$/.test(i.id)&&Object.hasOwn(templates,i.format)&&typeof i.approved==='boolean'&&(i.source===null||o.research.some(r=>r.id===i.source))&&(!i.edits||Object.entries(i.edits).every(([k,v])=>['title','hook','shots'].includes(k)&&typeof v==='string')))||new Set(o.ideas.map(i=>i.id)).size!==o.ideas.length||new Set(o.research.map(r=>r.id)).size!==o.research.length||o.ideas.filter(i=>i.approved).length>m.slots)throw Error();}
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
if(!state.ideas.length&&state.demo)generate();else render();
if(storageProblem)notice('Saved data could not be read. It has not been overwritten.');
